  prerequisite_lesson_id, created_at, updated_at
) VALUES
  ('5a257fa8-d3b9-4907-95d0-a35af52033c8', 'money_basics-advanced', 'Advanced Money Basics: behavioral biases in spending', 'Money Basics Lanjutan: bias perilaku', (SELECT id FROM topics WHERE slug = 'money_basics'), 10, 'advanced', 100, 10, 'Deep dive into advanced money basics concepts for experienced learners.', 'This lesson explores behavioral biases in spending and mental accounting at an advanced level, connecting theory to Indonesian market practice.', 'An unlicensed P2P lender uses ''social proof'' from fake testimonials. Design a consumer protection framework.', 'Mastering advanced money basics concepts enables sophisticated portfolio construction and risk management.', 'Applying intermediate-level heuristics to complex market conditions without updating mental models.', NULL, 'Advanced Money Basics discussion with Indonesian regulatory and market context.', 'draft', NULL, NULL, false, 'ID', (SELECT id FROM lessons WHERE slug = 'money-basics-101'), '2026-07-14T14:21:14.796167'::timestamptz, '2026-07-14T14:21:14.796167'::timestamptz),
  ('c0383cc6-0e6f-40a1-9e56-7e17a7f6fa0c', 'inflation-advanced', 'Advanced Inflation: Phillips curve', 'Inflation Lanjutan: kurva Phillips', (SELECT id FROM topics WHERE slug = 'inflation'), 11, 'advanced', 100, 10, 'Deep dive into advanced inflation concepts for experienced learners.', 'This lesson explores Phillips curve and Taylor rule at an advanced level, connecting theory to Indonesian market practice.', 'Indonesia''s debt-to-GDP is 41%. If BI monetizes 10% of new issuance, model the inflation risk over 5 years.', 'Mastering advanced inflation concepts enables sophisticated portfolio construction and risk management.', 'Applying intermediate-level heuristics to complex market conditions without updating mental models.', NULL, 'Advanced Inflation discussion with Indonesian regulatory and market context.', 'draft', NULL, NULL, false, 'ID', (SELECT id FROM lessons WHERE slug = 'inflation-101'), '2026-07-14T14:21:14.796172'::timestamptz, '2026-07-14T14:21:14.796173'::timestamptz),
  ('f18c6c7f-e92b-4cbb-983e-ac97bea869a2', 'budgeting-advanced', 'Advanced Budgeting: capital budgeting', 'Budgeting Lanjutan: anggaran modal', (SELECT id FROM topics WHERE slug = 'budgeting'), 12, 'advanced', 100, 10, 'Deep dive into advanced budgeting concepts for experienced learners.', 'This lesson explores capital budgeting and NPV vs IRR in personal finance at an advanced level, connecting theory to Indonesian market practice.', 'A 30-year-old professional must choose: MBA (Rp 500M cost, +30% salary) vs invest in property. Model NPV.', 'Mastering advanced budgeting concepts enables sophisticated portfolio construction and risk management.', 'Applying intermediate-level heuristics to complex market conditions without updating mental models.', NULL, 'Advanced Budgeting discussion with Indonesian regulatory and market context.', 'draft', NULL, NULL, false, 'ID', (SELECT id FROM lessons WHERE slug = 'budgeting-101'), '2026-07-14T14:21:14.796177'::timestamptz, '2026-07-14T14:21:14.796178'::timestamptz),
  ('b1d7b335-420c-443f-837a-fbfc7d0c6eba', 'risk_return-advanced', 'Advanced Risk & Return: Black-Scholes intuition', 'Risk & Return Lanjutan: Black-Scholes', (SELECT id FROM topics WHERE slug = 'risk_return'), 13, 'advanced', 100, 10, 'Deep dive into advanced risk & return concepts for experienced learners.', 'This lesson explores Black-Scholes intuition and Value at Risk (VaR) at an advanced level, connecting theory to Indonesian market practice.', 'A fund has daily returns with mean 0.05% and std dev 1.2%. Calculate 95% 1-day VaR for Rp 1B portfolio.', 'Mastering advanced risk & return concepts enables sophisticated portfolio construction and risk management.', 'Applying intermediate-level heuristics to complex market conditions without updating mental models.', NULL, 'Advanced Risk & Return discussion with Indonesian regulatory and market context.', 'draft', NULL, NULL, false, 'ID', (SELECT id FROM lessons WHERE slug = 'risk-return-101'), '2026-07-14T14:21:14.796181'::timestamptz, '2026-07-14T14:21:14.796182'::timestamptz),
  ('76920839-bdd4-4f5f-a266-8b7d4d50ea32', 'idx_basics-advanced', 'Advanced IDX Basics: market microstructure', 'IDX Basics Lanjutan: mikrostruktur pasar', (SELECT id FROM topics WHERE slug = 'idx_basics'), 14, 'advanced', 100, 10, 'Deep dive into advanced idx basics concepts for experienced learners.', 'This lesson explores market microstructure and bid-ask spread analysis at an advanced level, connecting theory to Indonesian market practice.', 'Analyze how tick size reduction (from Rp 25 to Rp 1 for stocks <Rp 200) affected liquidity and bid-ask spreads.', 'Mastering advanced idx basics concepts enables sophisticated portfolio construction and risk management.', 'Applying intermediate-level heuristics to complex market conditions without updating mental models.', NULL, 'Advanced IDX Basics discussion with Indonesian regulatory and market context.', 'draft', NULL, NULL, false, 'ID', (SELECT id FROM lessons WHERE slug = 'idx-basics-101'), '2026-07-14T14:21:14.796186'::timestamptz, '2026-07-14T14:21:14.796186'::timestamptz),
  ('9dea2348-ea0e-4958-9839-1b6a68b656f9', 'behavioral_finance-advanced', 'Advanced Behavioral Finance: bounded rationality', 'Behavioral Finance Lanjutan: rasionalitas terbatas', (SELECT id FROM topics WHERE slug = 'behavioral_finance'), 15, 'advanced', 100, 10, 'Deep dive into advanced behavioral finance concepts for experienced learners.', 'This lesson explores bounded rationality and adaptive markets hypothesis at an advanced level, connecting theory to Indonesian market practice.', 'The adaptive markets hypothesis suggests market efficiency varies with ecological conditions. Apply this to IDX during crisis vs boom.', 'Mastering advanced behavioral finance concepts enables sophisticated portfolio construction and risk management.', 'Applying intermediate-level heuristics to complex market conditions without updating mental models.', NULL, 'Advanced Behavioral Finance discussion with Indonesian regulatory and market context.', 'draft', NULL, NULL, false, 'ID', (SELECT id FROM lessons WHERE slug = 'volatility-101'), '2026-07-14T14:21:14.796190'::timestamptz, '2026-07-14T14:21:14.796191'::timestamptz)
ON CONFLICT (id) DO NOTHING;


