  ('money-basics-101', 'question', '{"question": "If you save Rp 1,000,000 monthly at 6% annual interest compounded monthly, how much will you have after 5 years?", "answer": "69,770,000", "explanation": "Using the future value of an annuity formula: FV = PMT × [(1+r)^n - 1]/r. With r = 0.5% monthly, n = 60, PMT = 1,000,000. FV ≈ Rp 69.77M.", "type": "calculation", "difficulty": "beginner", "parameters": {"hint": "Use FV annuity formula with monthly compounding."}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.791280'::timestamptz),
  ('money-basics-101', 'question', '{"question": "A stock costs Rp 5,000 per share. You buy 200 shares. After 1 year, the price is Rp 6,200. What is your percentage return?", "answer": "24%", "explanation": "Initial investment: 200 × 5,000 = 1,000,000. Final value: 200 × 6,200 = 1,240,000. Return = (1,240,000 - 1,000,000) / 1,000,000 = 24%.", "type": "calculation", "difficulty": "beginner", "parameters": {"hint": "Calculate total initial cost, total final value, then percentage change."}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.791290'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Using the Rule of 72, how many years does it take to double money at 8% annual return?", "answer": "9", "explanation": "Rule of 72: Years to double = 72 / interest rate. 72 / 8 = 9 years.", "type": "calculation", "difficulty": "beginner", "parameters": {"hint": "Divide 72 by the annual return percentage."}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.791298'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Your savings account pays 3% interest annually. Inflation is 5%. What is your approximate real return?", "answer": "-2%", "explanation": "Real return ≈ nominal return - inflation rate = 3% - 5% = -2%. Your purchasing power is declining.", "type": "calculation", "difficulty": "intermediate", "parameters": {"hint": "Subtract inflation from the nominal interest rate."}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.791306'::timestamptz),
  ('money-basics-101', 'question', '{"question": "You have Rp 50M to invest. You allocate 60% to stocks (expected 10% return) and 40% to bonds (expected 5% return). What is the expected portfolio return?", "answer": "8%", "explanation": "Weighted return = (0.60 × 10%) + (0.40 × 5%) = 6% + 2% = 8%.", "type": "calculation", "difficulty": "intermediate", "parameters": {"hint": "Multiply each allocation by its return and sum the results."}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.791314'::timestamptz),
  ('money-basics-101', 'question', '{"question": "A company has net income of Rp 100B and 10B shares outstanding. What is the EPS?", "answer": "10", "explanation": "EPS = Net Income / Shares Outstanding = 100B / 10B = Rp 10 per share.", "type": "calculation", "difficulty": "intermediate", "parameters": {"hint": "Divide total net income by the number of shares."}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.791320'::timestamptz),
  ('money-basics-101', 'question', '{"question": "A stock trades at Rp 20,000 with EPS of Rp 1,000. What is the P/E ratio?", "answer": "20", "explanation": "P/E = Price per share / Earnings per share = 20,000 / 1,000 = 20.", "type": "calculation", "difficulty": "advanced", "parameters": {"hint": "Divide stock price by earnings per share."}}'::jsonb, 'advanced', 'money_basics', true, '2026-07-14T14:21:14.791326'::timestamptz),
  ('money-basics-101', 'question', '{"question": "If Rp 100M grows to Rp 150M in 5 years, what is the approximate annual compound growth rate (CAGR)?", "answer": "8.4%", "explanation": "CAGR = (Ending Value / Beginning Value)^(1/n) - 1 = (150/100)^(1/5) - 1 ≈ 8.4%.", "type": "calculation", "difficulty": "advanced", "parameters": {"hint": "Use the CAGR formula: (FV/PV)^(1/years) - 1."}}'::jsonb, 'advanced', 'money_basics', true, '2026-07-14T14:21:14.791333'::timestamptz),
  ('money-basics-101', 'question', '{"question": "You earn Rp 8M monthly. Following the 50/30/20 rule, how much should go to savings and debt?", "answer": "1,600,000", "explanation": "20% of 8,000,000 = 0.20 × 8,000,000 = Rp 1,600,000.", "type": "calculation", "difficulty": "advanced", "parameters": {"hint": "Calculate 20% of the monthly income."}}'::jsonb, 'advanced', 'money_basics', true, '2026-07-14T14:21:14.791339'::timestamptz),
  ('inflation-101', 'question', '{"question": "A portfolio has 50% stocks (beta 1.2), 30% bonds (beta 0.3), 20% cash (beta 0). What is the portfolio beta?", "answer": "0.69", "explanation": "Portfolio beta = (0.50 × 1.2) + (0.30 × 0.3) + (0.20 × 0) = 0.60 + 0.09 + 0 = 0.69.", "type": "calculation", "difficulty": "beginner", "parameters": {"hint": "Weight each asset''s beta by its portfolio allocation."}}'::jsonb, 'beginner', 'inflation', true, '2026-07-14T14:21:14.791345'::timestamptz),
  ('inflation-101', 'question', '{"question": "If you save Rp 1,000,000 monthly at 6% annual interest compounded monthly, how much will you have after 5 years?", "answer": "69,770,000", "explanation": "Using the future value of an annuity formula: FV = PMT × [(1+r)^n - 1]/r. With r = 0.5% monthly, n = 60, PMT = 1,000,000. FV ≈ Rp 69.77M.", "type": "calculation", "difficulty": "beginner", "parameters": {"hint": "Use FV annuity formula with monthly compounding."}}'::jsonb, 'beginner', 'inflation', true, '2026-07-14T14:21:14.791352'::timestamptz),
  ('inflation-101', 'question', '{"question": "A stock costs Rp 5,000 per share. You buy 200 shares. After 1 year, the price is Rp 6,200. What is your percentage return?", "answer": "24%", "explanation": "Initial investment: 200 × 5,000 = 1,000,000. Final value: 200 × 6,200 = 1,240,000. Return = (1,240,000 - 1,000,000) / 1,000,000 = 24%.", "type": "calculation", "difficulty": "beginner", "parameters": {"hint": "Calculate total initial cost, total final value, then percentage change."}}'::jsonb, 'beginner', 'inflation', true, '2026-07-14T14:21:14.791358'::timestamptz),
  ('inflation-101', 'question', '{"question": "Using the Rule of 72, how many years does it take to double money at 8% annual return?", "answer": "9", "explanation": "Rule of 72: Years to double = 72 / interest rate. 72 / 8 = 9 years.", "type": "calculation", "difficulty": "intermediate", "parameters": {"hint": "Divide 72 by the annual return percentage."}}'::jsonb, 'intermediate', 'inflation', true, '2026-07-14T14:21:14.791364'::timestamptz),
  ('inflation-101', 'question', '{"question": "Your savings account pays 3% interest annually. Inflation is 5%. What is your approximate real return?", "answer": "-2%", "explanation": "Real return ≈ nominal return - inflation rate = 3% - 5% = -2%. Your purchasing power is declining.", "type": "calculation", "difficulty": "intermediate", "parameters": {"hint": "Subtract inflation from the nominal interest rate."}}'::jsonb, 'intermediate', 'inflation', true, '2026-07-14T14:21:14.791371'::timestamptz),
  ('inflation-101', 'question', '{"question": "You have Rp 50M to invest. You allocate 60% to stocks (expected 10% return) and 40% to bonds (expected 5% return). What is the expected portfolio return?", "answer": "8%", "explanation": "Weighted return = (0.60 × 10%) + (0.40 × 5%) = 6% + 2% = 8%.", "type": "calculation", "difficulty": "intermediate", "parameters": {"hint": "Multiply each allocation by its return and sum the results."}}'::jsonb, 'intermediate', 'inflation', true, '2026-07-14T14:21:14.791377'::timestamptz),
  ('inflation-101', 'question', '{"question": "A company has net income of Rp 100B and 10B shares outstanding. What is the EPS?", "answer": "10", "explanation": "EPS = Net Income / Shares Outstanding = 100B / 10B = Rp 10 per share.", "type": "calculation", "difficulty": "advanced", "parameters": {"hint": "Divide total net income by the number of shares."}}'::jsonb, 'advanced', 'inflation', true, '2026-07-14T14:21:14.791383'::timestamptz),
  ('inflation-101', 'question', '{"question": "A stock trades at Rp 20,000 with EPS of Rp 1,000. What is the P/E ratio?", "answer": "20", "explanation": "P/E = Price per share / Earnings per share = 20,000 / 1,000 = 20.", "type": "calculation", "difficulty": "advanced", "parameters": {"hint": "Divide stock price by earnings per share."}}'::jsonb, 'advanced', 'inflation', true, '2026-07-14T14:21:14.791389'::timestamptz),
  ('inflation-101', 'question', '{"question": "If Rp 100M grows to Rp 150M in 5 years, what is the approximate annual compound growth rate (CAGR)?", "answer": "8.4%", "explanation": "CAGR = (Ending Value / Beginning Value)^(1/n) - 1 = (150/100)^(1/5) - 1 ≈ 8.4%.", "type": "calculation", "difficulty": "advanced", "parameters": {"hint": "Use the CAGR formula: (FV/PV)^(1/years) - 1."}}'::jsonb, 'advanced', 'inflation', true, '2026-07-14T14:21:14.791395'::timestamptz),
