  ('money-basics-101', 'question', '{"question": "Which is generally safer: keeping Rp 50M in an OJK-licensed bank deposit or investing in an unlicensed P2P platform promising 15% returns?", "options": ["OJK-licensed bank deposit", "Unlicensed P2P platform", "Both equally safe", "Cannot determine"], "answer": "OJK-licensed bank deposit", "explanation": "Licensed deposits are regulated and insured. Unlicensed platforms carry fraud risk and no investor protection.", "type": "comparison", "difficulty": "beginner", "parameters": {}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.791676'::timestamptz),
  ('money-basics-101', 'question', '{"question": "For a 25-year-old with stable income: is it better to prioritize paying off low-interest student loans or start investing early?", "options": ["Pay off loans first completely", "Start investing early", "Do neither, spend on experiences", "Split equally"], "answer": "Start investing early", "explanation": "At a young age, the power of compounding favors starting investments early, while low-interest loans can be managed alongside.", "type": "comparison", "difficulty": "beginner", "parameters": {}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.791685'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Compare lump sum investing vs dollar cost averaging (DCA) in a volatile market. Which typically reduces timing risk?", "options": ["Lump sum investing", "Dollar cost averaging", "Both eliminate timing risk", "Neither helps"], "answer": "Dollar cost averaging", "explanation": "DCA spreads purchases over time, reducing the impact of investing at a market peak.", "type": "comparison", "difficulty": "beginner", "parameters": {}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.791693'::timestamptz),
