  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI invested all my savings in one stock because my friend said it was a ''sure thing.'' I also didn''t check if the broker was OJK-licensed. I''m sure I''ll double my money in 3 months!", "options": ["Concentrated all savings in one stock", "Trusted friend''s tip without research", "Didn''t verify OJK license", "Expected guaranteed high returns in short time", "There are no mistakes", "Only one minor mistake"], "answer": ["Concentrated all savings in one stock", "Trusted friend''s tip without research", "Didn''t verify OJK license", "Expected guaranteed high returns in short time"], "explanation": "Multiple errors: no diversification, no due diligence, unrealistic return expectations, and unverified broker.", "type": "spot_mistake", "difficulty": "beginner", "parameters": {"mistake_count": 4}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.792065'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nMy budget allocates 70% to wants, 20% to needs, and 10% to savings. I also keep my emergency fund in cryptocurrency for higher returns.", "options": ["Inverted needs/wants ratio", "Savings rate too low", "Emergency fund in volatile asset", "No clear financial goals", "There are no mistakes", "Only one minor mistake"], "answer": ["Inverted needs/wants ratio", "Savings rate too low", "Emergency fund in volatile asset", "No clear financial goals"], "explanation": "Budget is upside-down, savings insufficient, and emergency funds must be liquid and safe.", "type": "spot_mistake", "difficulty": "beginner", "parameters": {"mistake_count": 4}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.792075'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI check my stock portfolio every hour and sell whenever it drops more than 2%. I also buy whatever stock is trending on social media.", "options": ["Over-monitoring portfolio", "Panic selling on small dips", "Social media driven investing", "No long-term strategy", "There are no mistakes", "Only one minor mistake"], "answer": ["Over-monitoring portfolio", "Panic selling on small dips", "Social media driven investing", "No long-term strategy"], "explanation": "Emotional trading, no strategy, and social media tips are unreliable sources of investment decisions.", "type": "spot_mistake", "difficulty": "beginner", "parameters": {"mistake_count": 4}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.792084'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI put all my money in a ''guaranteed 20% monthly return'' scheme. The person running it says it''s secret and I shouldn''t tell anyone. I signed up immediately.", "options": ["Unrealistic return promise", "Secrecy requirement is red flag", "No verification of legitimacy", "Invested all money", "There are no mistakes", "Only one minor mistake"], "answer": ["Unrealistic return promise", "Secrecy requirement is red flag", "No verification of legitimacy", "Invested all money"], "explanation": "This exhibits classic Ponzi scheme warning signs: guaranteed high returns, secrecy, and pressure to act fast.", "type": "spot_mistake", "difficulty": "intermediate", "parameters": {"mistake_count": 4}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.792094'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI use my credit card for all purchases because I get cashback. I only pay the minimum balance each month. I have Rp 50M in credit card debt.", "options": ["Carrying high credit card balance", "Only paying minimum", "Using credit for routine purchases without plan", "Accumulating 2.5% monthly interest", "There are no mistakes", "Only one minor mistake"], "answer": ["Carrying high credit card balance", "Only paying minimum", "Using credit for routine purchases without plan", "Accumulating 2.5% monthly interest"], "explanation": "Credit card debt at 2.5% monthly compounds to devastating levels. Minimum payments prolong debt for years.", "type": "spot_mistake", "difficulty": "intermediate", "parameters": {"mistake_count": 4}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.792103'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI don''t need to budget because I can always check my e-wallet balance. I have 5 different e-wallets and I''m not sure how much I spend total each month.", "options": ["No budgeting system", "Fragmented spending across platforms", "No expense tracking", "Relies on checking balance reactively", "There are no mistakes", "Only one minor mistake"], "answer": ["No budgeting system", "Fragmented spending across platforms", "No expense tracking", "Relies on checking balance reactively"], "explanation": "Without tracking and budgeting, spending easily exceeds income without awareness.", "type": "spot_mistake", "difficulty": "intermediate", "parameters": {"mistake_count": 4}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.792112'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI sold my profitable stocks to realize gains but kept my losing stocks hoping they''d recover. I read one article that confirmed the losers would bounce back.", "options": ["Disposition effect", "Confirmation bias", "No stop-loss strategy", "Emotion-driven decisions", "There are no mistakes", "Only one minor mistake"], "answer": ["Disposition effect", "Confirmation bias", "No stop-loss strategy", "Emotion-driven decisions"], "explanation": "The disposition effect (selling winners, holding losers) and confirmation bias destroy long-term returns.", "type": "spot_mistake", "difficulty": "advanced", "parameters": {"mistake_count": 4}}'::jsonb, 'advanced', 'money_basics', true, '2026-07-14T14:21:14.792121'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI''m 22 and I think investing is only for old people. I''ll start when I have a ''real job.'' My money stays in a checking account earning 0% interest.", "options": ["Age-based investment procrastination", "0% return on idle cash", "Missed compounding opportunity", "False prerequisite beliefs", "There are no mistakes", "Only one minor mistake"], "answer": ["Age-based investment procrastination", "0% return on idle cash", "Missed compounding opportunity", "False prerequisite beliefs"], "explanation": "Starting young maximizes compounding. Even small amounts invested early outperform larger amounts invested later.", "type": "spot_mistake", "difficulty": "advanced", "parameters": {"mistake_count": 4}}'::jsonb, 'advanced', 'money_basics', true, '2026-07-14T14:21:14.792130'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI invest based on my horoscope and the advice of a WhatsApp group admin who claims to have insider information. I never read financial statements.", "options": ["Superstition-based investing", "Unverified insider claims", "No fundamental analysis", "Following unqualified advice", "There are no mistakes", "Only one minor mistake"], "answer": ["Superstition-based investing", "Unverified insider claims", "No fundamental analysis", "Following unqualified advice"], "explanation": "Investment decisions should be based on research and fundamentals, not superstition or unverified tips.", "type": "spot_mistake", "difficulty": "advanced", "parameters": {"mistake_count": 4}}'::jsonb, 'advanced', 'money_basics', true, '2026-07-14T14:21:14.792139'::timestamptz),
