  ('idx-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nMy budget allocates 70% to wants, 20% to needs, and 10% to savings. I also keep my emergency fund in cryptocurrency for higher returns.", "options": ["Inverted needs/wants ratio", "Savings rate too low", "Emergency fund in volatile asset", "No clear financial goals", "There are no mistakes", "Only one minor mistake"], "answer": ["Inverted needs/wants ratio", "Savings rate too low", "Emergency fund in volatile asset", "No clear financial goals"], "explanation": "Budget is upside-down, savings insufficient, and emergency funds must be liquid and safe.", "type": "spot_mistake", "difficulty": "intermediate", "parameters": {"mistake_count": 4}}'::jsonb, 'intermediate', 'idx_basics', true, '2026-07-14T14:21:14.792415'::timestamptz),
  ('idx-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI check my stock portfolio every hour and sell whenever it drops more than 2%. I also buy whatever stock is trending on social media.", "options": ["Over-monitoring portfolio", "Panic selling on small dips", "Social media driven investing", "No long-term strategy", "There are no mistakes", "Only one minor mistake"], "answer": ["Over-monitoring portfolio", "Panic selling on small dips", "Social media driven investing", "No long-term strategy"], "explanation": "Emotional trading, no strategy, and social media tips are unreliable sources of investment decisions.", "type": "spot_mistake", "difficulty": "advanced", "parameters": {"mistake_count": 4}}'::jsonb, 'advanced', 'idx_basics', true, '2026-07-14T14:21:14.792423'::timestamptz),
  ('idx-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI put all my money in a ''guaranteed 20% monthly return'' scheme. The person running it says it''s secret and I shouldn''t tell anyone. I signed up immediately.", "options": ["Unrealistic return promise", "Secrecy requirement is red flag", "No verification of legitimacy", "Invested all money", "There are no mistakes", "Only one minor mistake"], "answer": ["Unrealistic return promise", "Secrecy requirement is red flag", "No verification of legitimacy", "Invested all money"], "explanation": "This exhibits classic Ponzi scheme warning signs: guaranteed high returns, secrecy, and pressure to act fast.", "type": "spot_mistake", "difficulty": "advanced", "parameters": {"mistake_count": 4}}'::jsonb, 'advanced', 'idx_basics', true, '2026-07-14T14:21:14.792431'::timestamptz),
  ('idx-basics-101', 'question', '{"question": "Read the following statement and identify the financial mistakes:\n\nI use my credit card for all purchases because I get cashback. I only pay the minimum balance each month. I have Rp 50M in credit card debt.", "options": ["Carrying high credit card balance", "Only paying minimum", "Using credit for routine purchases without plan", "Accumulating 2.5% monthly interest", "There are no mistakes", "Only one minor mistake"], "answer": ["Carrying high credit card balance", "Only paying minimum", "Using credit for routine purchases without plan", "Accumulating 2.5% monthly interest"], "explanation": "Credit card debt at 2.5% monthly compounds to devastating levels. Minimum payments prolong debt for years.", "type": "spot_mistake", "difficulty": "advanced", "parameters": {"mistake_count": 4}}'::jsonb, 'advanced', 'idx_basics', true, '2026-07-14T14:21:14.792440'::timestamptz),
