  ('money-basics-101', 'question', '{"question": "Decision Tree Scenario:\n\nYou unexpectedly receive Rp 100M. You have Rp 30M in credit card debt at 2.5% monthly interest, no emergency fund, and no investments.\n\nFirst priority: What do you do with the first portion?", "options": ["Invest in stocks for high returns", "Pay off all credit card debt", "Build emergency fund", "Buy a new car"], "answer": "Pay off all credit card debt", "explanation": "Correct path: Pay off all credit card debt. This represents the most financially sound decision at this stage.", "type": "decision_tree", "difficulty": "beginner", "parameters": {"full_tree": {"scenario": "You unexpectedly receive Rp 100M. You have Rp 30M in credit card debt at 2.5% monthly interest, no emergency fund, and no investments.", "stages": [{"question": "First priority: What do you do with the first portion?", "options": ["Invest in stocks for high returns", "Pay off all credit card debt", "Build emergency fund", "Buy a new car"], "correct": "Pay off all credit card debt", "next": {"question": "After paying debt, you have Rp 70M left. Next step?", "options": ["Invest everything in crypto", "Build 6-month emergency fund", "Start a business", "Luxury vacation"], "correct": "Build 6-month emergency fund", "next": {"question": "With emergency fund set, Rp 50M remains. Final decision?", "options": ["All in one stock", "Diversified index fund portfolio", "Keep in savings", "Lend to a friend"], "correct": "Diversified index fund portfolio"}}}]}}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.794139'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Decision Tree Scenario:\n\nYou are 28, earning Rp 15M/month, with no savings. You want to buy a house in 7 years.\n\nMonth 1: How much should you save first?", "options": ["Rp 500K", "Rp 3M (20% of income)", "Rp 7.5M (50% of income)", "Nothing, spend freely"], "answer": "Rp 3M (20% of income)", "explanation": "Correct path: Rp 3M (20% of income). This represents the most financially sound decision at this stage.", "type": "decision_tree", "difficulty": "beginner", "parameters": {"full_tree": {"scenario": "You are 28, earning Rp 15M/month, with no savings. You want to buy a house in 7 years.", "stages": [{"question": "Month 1: How much should you save first?", "options": ["Rp 500K", "Rp 3M (20% of income)", "Rp 7.5M (50% of income)", "Nothing, spend freely"], "correct": "Rp 3M (20% of income)", "next": {"question": "Where should you keep the emergency portion (3 months expenses = Rp 45M target)?", "options": ["Crypto wallet", "High-yield savings", "Stock market", "Under mattress"], "correct": "High-yield savings", "next": {"question": "After emergency fund, monthly surplus goes to house fund. Best vehicle?", "options": ["Regular savings", "Money market fund", "Aggressive growth stocks", "Friends'' business"], "correct": "Money market fund"}}}]}}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.794151'::timestamptz),
  ('money-basics-101', 'question', '{"question": "Decision Tree Scenario:\n\nThe stock market drops 20% in one month. You have Rp 200M invested across 10 stocks.\n\nFirst reaction: What do you check?", "options": ["Sell everything immediately", "Check if fundamentals changed", "Check social media sentiment", "Buy more on margin"], "answer": "Check if fundamentals changed", "explanation": "Correct path: Check if fundamentals changed. This represents the most financially sound decision at this stage.", "type": "decision_tree", "difficulty": "beginner", "parameters": {"full_tree": {"scenario": "The stock market drops 20% in one month. You have Rp 200M invested across 10 stocks.", "stages": [{"question": "First reaction: What do you check?", "options": ["Sell everything immediately", "Check if fundamentals changed", "Check social media sentiment", "Buy more on margin"], "correct": "Check if fundamentals changed", "next": {"question": "Fundamentals are intact. What action makes sense?", "options": ["Panic sell to preserve capital", "Hold and consider buying more", "Switch to gold entirely", "Blame the government"], "correct": "Hold and consider buying more", "next": {"question": "You decide to buy more. Best approach?", "options": ["All remaining cash at once", "Dollar cost average over 3 months", "Wait for ''the bottom''", "Borrow to invest"], "correct": "Dollar cost average over 3 months"}}}]}}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.794163'::timestamptz),
