  ('money-basics-101', 'question', '{"question": "[IMAGE: A line chart showing the IDX Composite (IHSG) from 2019 to 2024. Sharp drop in March 2020, gradual recovery through 2021, volatility in 2022, steady climb in 2023-2024.]\n\nWhat does this chart primarily demonstrate about long-term investing?", "options": ["Markets always crash permanently", "Short-term volatility is normal, long-term trend matters", "Timing the market is easy", "Indonesian stocks are too risky"], "answer": "Short-term volatility is normal, long-term trend matters", "explanation": "The chart shows significant short-term drops but a long-term upward trend, illustrating why time in market beats timing the market.", "type": "image_interpretation", "difficulty": "beginner", "parameters": {"image_description": "A line chart showing the IDX Composite (IHSG) from 2019 to 2024. Sharp drop in March 2020, gradual recovery through 2021, volatility in 2022, steady climb in 2023-2024."}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.794709'::timestamptz),
  ('money-basics-101', 'question', '{"question": "[IMAGE: A pie chart showing asset allocation: 50% stocks, 30% bonds, 15% cash, 5% gold. Labels show this is a moderate risk portfolio.]\n\nWhat type of investor does this asset allocation most likely represent?", "options": ["Ultra-conservative", "Moderate risk tolerance", "Aggressive growth seeker", "Speculative trader"], "answer": "Moderate risk tolerance", "explanation": "A 50/30/15/5 split between stocks, bonds, cash, and gold represents balanced risk — neither too conservative nor too aggressive.", "type": "image_interpretation", "difficulty": "beginner", "parameters": {"image_description": "A pie chart showing asset allocation: 50% stocks, 30% bonds, 15% cash, 5% gold. Labels show this is a moderate risk portfolio."}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.794718'::timestamptz),
  ('money-basics-101', 'question', '{"question": "[IMAGE: A bar chart comparing inflation rate (3%) vs savings account interest (2%) vs stock market average return (10%) over 10 years.]\n\nWhat key insight does this comparison reveal?", "options": ["Savings accounts beat inflation", "Stocks have historically outpaced inflation", "All investments are equal", "Cash is the best store of value"], "answer": "Stocks have historically outpaced inflation", "explanation": "The chart shows that while savings lose purchasing power to inflation, equities have historically provided returns that exceed inflation.", "type": "image_interpretation", "difficulty": "beginner", "parameters": {"image_description": "A bar chart comparing inflation rate (3%) vs savings account interest (2%) vs stock market average return (10%) over 10 years."}}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.794727'::timestamptz),
  ('money-basics-101', 'question', '{"question": "[IMAGE: A candlestick chart of a single stock over 30 days. Prices swing between Rp 8,000 and Rp 9,500 with no clear trend.]\n\nWhat conclusion can be drawn from this price action?", "options": ["The stock is definitely going up", "The stock is in a consolidation phase", "Sell immediately", "Guaranteed profit opportunity"], "answer": "The stock is in a consolidation phase", "explanation": "Sideways movement without clear trend typically indicates consolidation, where buyers and sellers are in equilibrium.", "type": "image_interpretation", "difficulty": "intermediate", "parameters": {"image_description": "A candlestick chart of a single stock over 30 days. Prices swing between Rp 8,000 and Rp 9,500 with no clear trend."}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.794735'::timestamptz),
  ('money-basics-101', 'question', '{"question": "[IMAGE: An infographic showing compound growth: Rp 1M invested monthly at 7% annual return grows to Rp 1.2B over 30 years vs only Rp 360M without interest.]\n\nWhat principle is this infographic illustrating?", "options": ["Market timing", "The power of compound interest", "Day trading profits", "Currency hedging"], "answer": "The power of compound interest", "explanation": "The dramatic difference between simple accumulation and compound growth demonstrates why starting early and staying invested matters.", "type": "image_interpretation", "difficulty": "intermediate", "parameters": {"image_description": "An infographic showing compound growth: Rp 1M invested monthly at 7% annual return grows to Rp 1.2B over 30 years vs only Rp 360M without interest."}}'::jsonb, 'intermediate', 'money_basics', true, '2026-07-14T14:21:14.794743'::timestamptz),
