  ('budgeting-101', 'question', '{"question": "[IMAGE: A bar chart comparing inflation rate (3%) vs savings account interest (2%) vs stock market average return (10%) over 10 years.]\n\nWhat key insight does this comparison reveal?", "options": ["Savings accounts beat inflation", "Stocks have historically outpaced inflation", "All investments are equal", "Cash is the best store of value"], "answer": "Stocks have historically outpaced inflation", "explanation": "The chart shows that while savings lose purchasing power to inflation, equities have historically provided returns that exceed inflation.", "type": "image_interpretation", "difficulty": "intermediate", "parameters": {"image_description": "A bar chart comparing inflation rate (3%) vs savings account interest (2%) vs stock market average return (10%) over 10 years."}}'::jsonb, 'intermediate', 'budgeting', true, '2026-07-14T14:21:14.794891'::timestamptz),
  ('budgeting-101', 'question', '{"question": "[IMAGE: A candlestick chart of a single stock over 30 days. Prices swing between Rp 8,000 and Rp 9,500 with no clear trend.]\n\nWhat conclusion can be drawn from this price action?", "options": ["The stock is definitely going up", "The stock is in a consolidation phase", "Sell immediately", "Guaranteed profit opportunity"], "answer": "The stock is in a consolidation phase", "explanation": "Sideways movement without clear trend typically indicates consolidation, where buyers and sellers are in equilibrium.", "type": "image_interpretation", "difficulty": "intermediate", "parameters": {"image_description": "A candlestick chart of a single stock over 30 days. Prices swing between Rp 8,000 and Rp 9,500 with no clear trend."}}'::jsonb, 'intermediate', 'budgeting', true, '2026-07-14T14:21:14.794899'::timestamptz),
  ('budgeting-101', 'question', '{"question": "[IMAGE: An infographic showing compound growth: Rp 1M invested monthly at 7% annual return grows to Rp 1.2B over 30 years vs only Rp 360M without interest.]\n\nWhat principle is this infographic illustrating?", "options": ["Market timing", "The power of compound interest", "Day trading profits", "Currency hedging"], "answer": "The power of compound interest", "explanation": "The dramatic difference between simple accumulation and compound growth demonstrates why starting early and staying invested matters.", "type": "image_interpretation", "difficulty": "advanced", "parameters": {"image_description": "An infographic showing compound growth: Rp 1M invested monthly at 7% annual return grows to Rp 1.2B over 30 years vs only Rp 360M without interest."}}'::jsonb, 'advanced', 'budgeting', true, '2026-07-14T14:21:14.794906'::timestamptz),
  ('budgeting-101', 'question', '{"question": "[IMAGE: A scatter plot showing risk (volatility) on X-axis and return on Y-axis. Multiple Indonesian stocks plotted. A diagonal line shows the efficient frontier.]\n\nWhat does the efficient frontier line represent?", "options": ["Highest return regardless of risk", "Optimal portfolios for each risk level", "The safest possible portfolio", "A guaranteed return threshold"], "answer": "Optimal portfolios for each risk level", "explanation": "The efficient frontier represents portfolios that offer the highest expected return for a given level of risk.", "type": "image_interpretation", "difficulty": "advanced", "parameters": {"image_description": "A scatter plot showing risk (volatility) on X-axis and return on Y-axis. Multiple Indonesian stocks plotted. A diagonal line shows the efficient frontier."}}'::jsonb, 'advanced', 'budgeting', true, '2026-07-14T14:21:14.794914'::timestamptz),
  ('budgeting-101', 'question', '{"question": "[IMAGE: A flowchart: Start → Check OJK license → If yes: proceed to research → If no: stop and report. Branches show safe vs unsafe paths.]\n\nWhat is the FIRST checkpoint in this financial safety flowchart?", "options": ["Read the prospectus", "Check OJK license", "Calculate potential returns", "Ask friends for opinion"], "answer": "Check OJK license", "explanation": "The flowchart explicitly shows OJK license verification as the first decision point before any further action.", "type": "image_interpretation", "difficulty": "advanced", "parameters": {"image_description": "A flowchart: Start → Check OJK license → If yes: proceed to research → If no: stop and report. Branches show safe vs unsafe paths."}}'::jsonb, 'advanced', 'budgeting', true, '2026-07-14T14:21:14.794921'::timestamptz),
  ('risk-return-101', 'question', '{"question": "[IMAGE: A histogram showing distribution of monthly returns for the IDX Composite over 20 years. Most months cluster around 0-2%, with tails extending to -15% and +15%.]\n\nWhat does the shape of this distribution suggest about market returns?", "options": ["Returns are normally distributed", "Returns are predictable", "Most months are near average, extremes are rare", "Every month is equally likely"], "answer": "Most months are near average, extremes are rare", "explanation": "The bell-shaped distribution with most data near the mean and fewer observations in the tails is characteristic of return distributions.", "type": "image_interpretation", "difficulty": "beginner", "parameters": {"image_description": "A histogram showing distribution of monthly returns for the IDX Composite over 20 years. Most months cluster around 0-2%, with tails extending to -15% and +15%."}}'::jsonb, 'beginner', 'risk_return', true, '2026-07-14T14:21:14.794929'::timestamptz),
  ('risk-return-101', 'question', '{"question": "[IMAGE: A dual-axis chart: left axis shows Rupiah/USD exchange rate rising (depreciating), right axis shows Jakarta Composite Index falling.]\n\nWhat relationship might this chart be illustrating?", "options": ["Currency appreciation helps stocks", "Currency depreciation and stock declines may be correlated", "Stocks and currency are unrelated", "Government controls both"], "answer": "Currency depreciation and stock declines may be correlated", "explanation": "Rupiah depreciation and stock market declines often occur together during periods of foreign capital outflows and risk aversion.", "type": "image_interpretation", "difficulty": "beginner", "parameters": {"image_description": "A dual-axis chart: left axis shows Rupiah/USD exchange rate rising (depreciating), right axis shows Jakarta Composite Index falling."}}'::jsonb, 'beginner', 'risk_return', true, '2026-07-14T14:21:14.794937'::timestamptz),
