  ('money-basics-101', 'example', '{"text": "Example: needs vs wants\n\nA friend offers you 50% guaranteed monthly returns on an investment. What do you do?\n\nThis illustrates how needs vs wants applies in a real Indonesian financial context. Understanding this scenario helps learners recognize similar situations in their own financial decisions.", "source_ids": ["ad0e8258-4e0a-4378-b257-4fd3628c6953", "7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.795136'::timestamptz),
