  ('money-basics-101', 'example', '{"text": "Example: scam awareness\n\nYou see an Instagram ad promising double your money in a week. What is the red flag?\n\nThis illustrates how scam awareness applies in a real Indonesian financial context. Understanding this scenario helps learners recognize similar situations in their own financial decisions.", "source_ids": ["ad0e8258-4e0a-4378-b257-4fd3628c6953", "7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}'::jsonb, 'beginner', 'money_basics', true, '2026-07-14T14:21:14.795149'::timestamptz),
